119	@layer base {
120	  * {
121	    @apply border-border outline-ring/50;
122	  }
123	  body {
124	    @apply bg-background text-foreground;
125	    font-family: var(--font-roobert), system-ui, -apple-system, sans-serif;
126	    -webkit-font-smoothing: antialiased;
127	    -moz-osx-font-smoothing: grayscale;
128	  }
129	  html {
130	    @apply scroll-smooth;
131	  }
132	}
