134	@layer utilities {
135	  .gradient-cyan {
136	    background: linear-gradient(90deg, #21cfff, #019ae6);
137	  }
138	  .gradient-cyan-text {
139	    background: linear-gradient(90deg, #21cfff, #019ae6);
140	    -webkit-background-clip: text;
141	    -webkit-text-fill-color: transparent;
142	    background-clip: text;
143	  }
144	  .bg-navy {
145	    background-color: #092245;
146	  }
147	  .bg-navy-deep {
148	    background-color: #082753;
149	  }
150	
151	  /* Webflow section spacing */
152	  .section-large {
153	    padding: 128px 5%;
154	  }
155	  .section-regular {
156	    padding: 64px 5%;
157	  }
158	
159	  /* Card hover from Webflow */
160	  .card-hover {
161	    transition: background-color 0.3s, border-color 0.4s, box-shadow 0.3s;
162	  }
163	  .card-hover:hover {
164	    background-color: #cdebfa;
165	    border-color: #009ce0;
166	  }
167	
168	  /* Shimmer animation */
169	  @keyframes shimmer {
170	    0% { background-position: 200% 0; }
171	    100% { background-position: -200% 0; }
172	  }
173	  .animate-shimmer {
174	    background: linear-gradient(90deg, #f0f0f0 25%, #e0e0e0 50%, #f0f0f0 75%);
175	    background-size: 200% 100%;
176	    animation: shimmer 1.5s ease-in-out infinite;
177	  }
178	}
